mapper.select:
SELECT FINPROD_ID,VDATE,sum(tradeAmt) tradeAmt,CCY from (
SELECT
  FEE.FINPROD_ID,
  CASE WHEN T1.MDATE IS NOT NULL AND T2.MDATE IS NOT NULL AND T1.MDATE > T2.MDATE THEN T1.MDATE
  WHEN T1.MDATE IS NOT NULL AND T2.MDATE IS NOT NULL AND T2.MDATE > T1.MDATE THEN T2.MDATE
  WHEN T1.MDATE IS NOT NULL AND T2.MDATE IS NULL THEN T1.MDATE
  WHEN T2.MDATE IS NOT NULL AND T1.MDATE IS NULL THEN T2.MDATE
  ELSE T3.VDATE END VDATE,
  FEE.TDY_UNPAID_INTINCEXP tradeAmt,
  T3.CCY
FROM
BOK_POSITION_PRDFEE FEE
LEFT JOIN TRD_PRODUCT_DEAL T1 ON FEE.FINPROD_ID = T1.FINPROD_ID AND T1.FINPROD_TYPE2 = #{SINGLE_FEE_TYPE_03}
  AND T1.MDATE < STR_TO_DATE(#{mdate}, '%Y-%m-%d') and t1.TRADE_STATUS = #{TRADE_STATUS_01} and t1.IS_CANCEL = #{N}
LEFT JOIN WFL_TRD_PRODUCT_DEAL T2 ON FEE.FINPROD_ID = T2.FINPROD_ID AND T2.FINPROD_TYPE2 = #{SINGLE_FEE_TYPE_03}
  AND T2.MDATE < STR_TO_DATE(#{mdate}, '%Y-%m-%d') and t2.TRADE_STATUS = #{TRADE_STATUS_01} and t2.IS_CANCEL = #{N}
LEFT JOIN FIN_PRODUCT T3 ON FEE.CHL_ID = T3.FINPROD_ID
LEFT JOIN FIN_PRODUCT_ADD fpa ON fee.FINPROD_ID = fpa.FINPROD_ID
WHERE FEE.FEE_TYPE IN ( #{C12}, #{C13}, #{C14},#{B09})
AND (FEE.FINPROD_ID = #{ptlId} OR fpa.PORTFOLIO_ID=#{ptlId})
AND FEE.CHL_ID = #{chlId}
AND FEE.TDY_UNPAID_INTINCEXP > 0
AND FEE.CDATE = STR_TO_DATE(#{mdate}, '%Y-%m-%d') - 1
AND NOT EXISTS (SELECT 1 FROM TRD_PRODUCT_DEAL TT1
        WHERE FEE.FINPROD_ID = TT1.FINPROD_ID AND TT1.FINPROD_TYPE2 = #{SINGLE_FEE_TYPE_03} and TT1.TRADE_STATUS = #{TRADE_STATUS_01} and TT1.IS_CANCEL = #{N}
        AND TT1.MDATE < STR_TO_DATE(#{mdate}, '%Y-%m-%d') AND TT1.MDATE > T1.MDATE
    )
AND NOT EXISTS (SELECT 1 FROM WFL_TRD_PRODUCT_DEAL TT1
        WHERE FEE.FINPROD_ID = TT1.FINPROD_ID AND TT1.FINPROD_TYPE2 = #{SINGLE_FEE_TYPE_03} and TT1.TRADE_STATUS = #{TRADE_STATUS_01} and TT1.IS_CANCEL = #{N}
        AND TT1.MDATE < STR_TO_DATE(#{mdate}, '%Y-%m-%d') AND TT1.MDATE > T2.MDATE
    )
    )
    group by FINPROD_ID,VDATE,CCY

SELECT deal.TRADE_ID FROM TRD_PRODUCT_DEAL deal
LEFT JOIN TRD_PRODUCT_DEAL_ADD t on deal.TRADE_ID = t.TRADE_ID 
WHERE deal.MDATE = #{mdate, jdbcType=DATE} AND deal.FINPROD_ID = #{finprodId}
                                        and deal.TRADE_STATUS = #{TRADE_STATUS_01} and deal.IS_CANCEL = #{N}
                                        and t.PORTFOLIO_ID = #{portfolioId}
UNION ALL
SELECT concat_ws('', wfl.TRADE_ID , '流程中') FROM WFL_TRD_PRODUCT_DEAL wfl
LEFT JOIN WFL_TRD_PRODUCT_DEAL_ADD wfladd on wfl.TRADE_ID = wfladd.TRADE_ID
WHERE wfl.MDATE = #{mdate, jdbcType=DATE} AND wfl.FINPROD_ID = #{finprodId}
                                            and wfl.TRADE_STATUS = #{TRADE_STATUS_01} and wfl.IS_CANCEL = #{N}
                                            and wfladd.PORTFOLIO_ID = #{portfolioId}

SELECT FINPROD_MARKET_ID id, IFNULL(FINPROD_ABBR, FINPROD_NAME) text, FINPROD_ID object
FROM FIN_PRODUCT

    FINPROD_TYPE2 = #{F28}
    AND IS_CHL = #{Y}

        AND (FINPROD_ID LIKE CONCAT_WS('', '%', #{search}, '%')
        OR FINPROD_ABBR LIKE CONCAT_WS('', '%', #{search}, '%')
        OR FINPROD_NAME LIKE CONCAT_WS('', '%', #{search}, '%'))


        AND FINPROD_MARKET_ID = #{initValue}
